"use strict";
(()=>{const root=document.getElementById('tracingQuizRoot');if(!root)return;const alphabet=[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'],shuffle=a=>[...a].sort(()=>Math.random()-.5),indices=shuffle(Array.from({length:24},(_,i)=>i+1)).slice(0,10);let index=0,score=0;const speak=text=>{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.78;window.speechSynthesis.speak(u)};function finish(){root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / 10</p><p class="game-feedback">'+(score===10?'Excellent alphabet-order practice!':'Good work! Trace the alphabet again and retry.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button class="practice-button journey-primary" id="traceAgain">Play again</button><a class="practice-button journey-secondary" href="letter-tracing.html">← Review Letter Tracing</a><a class="practice-button journey-secondary" href="early-learning.html?topic=poems">Next: Poems →</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:10,title:'Letter Tracing & Order Quiz',subtitle:'Practise the alphabet order used by Previous and Next while tracing.',filename:'learnwithus-letter-tracing-quiz.svg',url:'letter-tracing-quiz.html'});window.LearnWithUs?.recordQuiz?.('Letter tracing & order quiz',score,10,'letter-tracing-quiz.html');document.getElementById('traceAgain').onclick=()=>location.reload();}function round(){if(index>=10)return finish();const pos=indices[index],askAfter=index%2===0,anchor=alphabet[pos],answer=alphabet[pos+(askAfter?1:-1)],wrong=shuffle(alphabet.filter(x=>x!==answer&&x!==anchor)).slice(0,3);root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(index+1)+' of 10</p><p class="trace-quiz-glyph">'+anchor+'</p><p class="game-question">Which letter comes '+(askAfter?'after':'before')+' '+anchor+'?</p><div class="game-options" id="traceQuizOptions"></div><p class="game-feedback" id="traceQuizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="traceQuizNext" hidden>'+(index===9?'See score →':'Next →')+'</button></section>';const row=document.getElementById('traceQuizOptions'),fb=document.getElementById('traceQuizFeedback'),next=document.getElementById('traceQuizNext');shuffle([answer,...wrong]).forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>{const ok=v===answer;row.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===answer)x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');const msg=ok?'Correct answer! It is '+answer+'.':'Wrong answer. The correct answer is '+answer+'.';fb.textContent=msg;speak(msg);if(ok)score++;next.hidden=false;next.focus();};row.append(b)});next.onclick=()=>{index++;round()};}round();})();